css:
@import url('https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=DM+Sans:wght@300;400;500;600&display=swap');

/* ── Outer wrapper ── */
.invoice-box {
    max-width: 750px;
    margin: auto;
    font-family: 'DM Sans', 'Segoe UI', sans-serif;
    font-size: 17px;
    color: #333;
    border-radius: 14px;
    overflow: hidden;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.10);
}

/* ── Header ── */
.inv-header {
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    padding: 36px 40px 28px;
    color: white;
    position: relative;
    overflow: hidden;
}

.inv-header::before {
    content: '';
    position: absolute;
    top: -40px;
    right: -40px;
    width: 180px;
    height: 180px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.04);
}

.inv-header::after {
    content: '';
    position: absolute;
    bottom: -60px;
    left: 60px;
    width: 240px;
    height: 240px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.03);
}

.inv-title {
    font-family: 'DM Serif Display', Georgia, serif;
    font-size: 40px;
    font-weight: 400;
    letter-spacing: -0.5px;
    margin: 0 0 4px;
    color: white;
}

.inv-site {
    font-size: 15px;
    color: rgba(255, 255, 255, 0.55);
    font-weight: 300;
    letter-spacing: 0.5px;
    text-transform: uppercase;
}

/* ── Body ── */
.inv-body {
    background: #ffffff;
    padding: 0 40px 36px;
    border: 1px solid #f0f0f0;
    border-top: none;
    border-radius: 0 0 14px 14px;
}

/* ── Meta strip ── */
.inv-meta-strip {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 20px 0;
    border-bottom: 1px solid #f0f0f0;
    gap: 16px;
    flex-wrap: wrap;
}

.inv-id {
    font-size: 13px;
    color: #888;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 2px;
}

.inv-id-val {
    font-size: 16px;
    font-weight: 500;
    color: #1a1a2e;
}

.inv-status {
    background: #eaf3de;
    color: #3b6d11;
    font-size: 13px;
    font-weight: 500;
    letter-spacing: 0.6px;
    text-transform: uppercase;
    padding: 5px 14px;
    border-radius: 20px;
}

/* ── Sections ── */
.inv-section {
    padding: 24px 0 0;
}

.inv-label {
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    color: #888;
    margin-bottom: 12px;
    font-weight: 500;
}

/* ── Grid ── */
.inv-grid-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

/* ── Fields ── */
.inv-field {
    background: #f9fafb;
    border-radius: 10px;
    padding: 12px 14px;
}

.inv-field-label {
    font-size: 13px;
    color: #999;
    margin-bottom: 4px;
}

.inv-field-val {
    font-size: 16px;
    font-weight: 500;
    color: #1a1a2e;
}

/* ── Badge ── */
.inv-badge {
    display: inline-block;
    background: #EEEDFE;
    color: #3C3489;
    font-size: 14px;
    font-weight: 500;
    padding: 3px 10px;
    border-radius: 20px;
}

/* ── Divider ── */
.inv-divider {
    height: 1px;
    background: #f0f0f0;
    margin: 24px 0;
}

/* ── Amount table ── */
.inv-amount-table {
    width: 100%;
    border-collapse: collapse;
}

.inv-amount-table td {
    padding: 10px 0;
    font-size: 16px;
}

.inv-amount-table td:last-child {
    text-align: right;
}

.inv-amount-table tr:not(:last-child) td {
    border-bottom: 1px solid #f0f0f0;
}

.inv-muted {
    color: #777;
}

.inv-discount {
    color: #a32d2d;
}

/* ── Total row ── */
.inv-total-row td {
    font-size: 24px;
    font-weight: 600;
    color: #0f6e56;
    padding-top: 18px !important;
}

.inv-total-label {
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: 0.8px;
}

/* ── Footer ── */
.inv-footer {
    margin-top: 28px;
    text-align: center;
    font-size: 15px;
    color: #888;
    letter-spacing: 0.3px;
}

.inv-footer span {
    display: block;
    margin-top: 6px;
    font-size: 13px;
    color: #aaa;
}
